SELECT u_id, order_id, take_id, award_id, award_type, award_name, award_content, grant_type, grant_date FROM user_strategy_export WHERE stock_mq_state = 1
AND grant_state != 1 AND (mq_state = 2 OR (mq_state = 0 AND create_time < DATE_SUB(NOW(), INTERVAL 30 MINUTE))
OR (mq_state IN (1, 3) AND update_time < DATE_SUB(NOW(), INTERVAL 10 MINUTE))) LIMIT #{limit}

SELECT u_id, order_id, strategy_id, award_id FROM user_strategy_export
WHERE stock_mq_state IN (0, 2)
OR (stock_mq_state = 3 AND update_time < DATE_SUB(NOW(), INTERVAL 10 MINUTE)) ORDER BY create_time ASC LIMIT #{limit}
